import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it } from "vitest";
import { Tablero } from "../src/Tablero.jsx";

describe("Tablero de envíos", () => {
  it("muestra los seis envíos y cuántos están entregados", () => {
    render(<Tablero />);
    expect(screen.getAllByRole("listitem")).toHaveLength(6);
    expect(screen.getByText("Entregados: 1 de 6")).toBeInTheDocument();
  });

  it("avanzar dos veces deja el envío entregado y bloquea el botón", async () => {
    const user = userEvent.setup();
    render(<Tablero />);
    const avanzar = screen.getByRole("button", { name: "Avanzar envío a Avellaneda" });
    await user.click(avanzar);
    expect(screen.getByText(/Avellaneda: en ruta/)).toBeInTheDocument();
    await user.click(avanzar);
    expect(screen.getByText(/Avellaneda: entregado/)).toBeInTheDocument();
    expect(avanzar).toBeDisabled();
    expect(screen.getByText("Entregados: 2 de 6")).toBeInTheDocument();
  });

  it("el filtro deja solo los envíos en ruta", async () => {
    const user = userEvent.setup();
    render(<Tablero />);
    await user.selectOptions(screen.getByLabelText("Estado"), "en ruta");
    const filas = screen.getAllByRole("listitem");
    expect(filas).toHaveLength(2);
    expect(filas[0]).toHaveTextContent("San Martín");
    expect(filas[1]).toHaveTextContent("Tigre");
  });
});

