import { defineConfig } from "@playwright/test";

export default defineConfig({
  testDir: "e2e",
  use: { baseURL: "http://127.0.0.1:47642", trace: "retain-on-failure" },
  webServer: {
    command: "./node_modules/.bin/vite preview --port 47642 --strictPort",
    url: "http://127.0.0.1:47642",
  },
});

import { test, expect } from "@playwright/test";

test("un envío pasa de pendiente a entregado", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByText("Entregados: 1 de 6")).toBeVisible();
  const avanzar = page.getByRole("button", { name: "Avanzar envío a Avellaneda" });
  await avanzar.click();
  await avanzar.click();
  await expect(page.getByText(/Avellaneda: entregado/)).toBeVisible();
  await expect(avanzar).toBeDisabled();
  await expect(page.getByText("Entregados: 2 de 6")).toBeVisible();
});

test("la pantalla se ve como la foto guardada", async ({ page }) => {
  await page.setViewportSize({ width: 360, height: 420 });
  await page.goto("/");
  await expect(page).toHaveScreenshot("tablero.png");
});
